// widgetFixture is the drv-054 hand-built transcript (features/metrics/fixtures),
// generated by gen_widget.py. Its expected values are tabulated in
// features/metrics/README.md.
var widgetFixture = filepath.Join("..", "..", "features", "metrics", "fixtures", "widget.stream.jsonl")

func foldFixture(t *testing.T) *State {
	t.Helper()
	st := NewState()
	present, err := foldStream(widgetFixture, claudecode.Normalize, st)
	if err != nil || !present {
		t.Fatalf("fold fixture: present=%v err=%v", present, err)
	}
	return st
}

func deref[T any](p *T) any {
	if p == nil {
		return nil
	}
	return *p
}

func TestFoldWidgetFixture(t *testing.T) {
	st := foldFixture(t)
	diff := Diff{Available: true, Files: map[string]bool{"src/widget.go": true}, Lines: 4}
	got := st.Finalize(diff)

	checks := []struct {
		name      string
		got, want any
	}{
		{"tool_calls", got.ToolCalls, 20},
		{"calls_by_class", got.CallsByClass, map[string]int{"read": 4, "search": 3, "subagent": 1, "build": 2, "other": 1, "edit": 5, "test": 2, "vcs": 2}},
		{"wall_time_s", deref(got.WallTimeSeconds), 660.0},
		{"final_diff", got.FinalDiff, "available"},
		{"diff_files", deref(got.DiffFiles), 1},
		{"diff_lines", deref(got.DiffLines), 4},
		{"prefix_basis", got.PrefixBasis, "first-productive-edit"},
		{"exploration_prefix_calls", got.ExplorationPrefixCalls, 4},
		{"exploration_prefix_tokens", got.ExplorationPrefixTokens, 12000},
		{"search_prefix_calls", got.SearchPrefixCalls, 3},
		{"empty_searches", got.EmptySearches, 2},
		{"repeated_searches", got.RepeatedSearches, 1},
		{"files_read_distinct", got.FilesReadDistinct, 3},
		{"files_read_unused", got.FilesReadUnused, 2},
		{"wasted_context_ratio", deref(got.WastedContextRatio), 2.0 / 3.0},
		{"rereads", got.Rereads, 1},
		{"docs_read", got.DocsRead, []string{"AGENTS.md"}},
		{"first_doc_read_index", deref(got.FirstDocReadIndex), 0},
		{"env_discovery_errors", got.EnvDiscoveryErrors, 2},
		{"test_failures", got.TestFailures, 1},
		{"build_failures", got.BuildFailures, 0},
		{"edit_mechanics_errors", got.EditMechanicsErrors, 1},
		{"permission_denials", got.PermissionDenials, 1},
		{"other_errors", got.OtherErrors, 0},
		{"tries_to_first_successful_test", deref(got.TriesToFirstSuccessfulTest), 2},
		{"tries_to_first_successful_build", deref(got.TriesToFirstSuccessfulBuild), 2},
		{"tokens_to_first_green_test", deref(got.TokensToFirstGreenTest), 172800},
		{"time_to_first_green_test_s", deref(got.TimeToFirstGreenTestSeconds), 550.0},
		{"reverted_edits", deref(got.RevertedEdits), 1},
		{"model", got.ModelObserved, "claude-fixture-1"},
	}
	for _, c := range checks {
		if !reflect.DeepEqual(c.got, c.want) {
			t.Errorf("%s = %#v, want %#v", c.name, c.got, c.want)
		}
	}
}

// Without a final diff the prefix falls back to the first edit of any file, flagged,
// and the diff-dependent metrics are absent rather than guessed.
func TestFoldWithoutDiffFallsBackToFirstEdit(t *testing.T) {
	got := foldFixture(t).Finalize(Diff{})
	if got.FinalDiff != "unavailable" || got.PrefixBasis != "first-edit" {
		t.Fatalf("final_diff=%s prefix_basis=%s", got.FinalDiff, got.PrefixBasis)
	}
	// The first edit (Write scratch.go, call 10) has the same exploration before it
	// as the productive one (call 11).
	if got.ExplorationPrefixCalls != 4 || got.SearchPrefixCalls != 3 {
		t.Fatalf("prefix = %d/%d", got.ExplorationPrefixCalls, got.SearchPrefixCalls)
	}
	if got.RevertedEdits != nil || got.DiffFiles != nil {
		t.Fatalf("diff-dependent metrics must be nil without a diff")
	}
	// Unused reads fall back to "read but never edited": widget.go was edited.
	if got.FilesReadUnused != 2 {
		t.Fatalf("files_read_unused = %d", got.FilesReadUnused)
	}
}

// Finalize does not mutate the fold, so a live consumer can finalize repeatedly
// and keep stepping.
func TestFinalizeIsRepeatable(t *testing.T) {
	st := foldFixture(t)
	d := Diff{Available: true, Files: map[string]bool{"src/widget.go": true}}
	a, b := st.Finalize(d), st.Finalize(d)
	if !reflect.DeepEqual(a, b) {
		t.Fatal("two finalizes differ")
	}
}

// One message's usage repeated on several content-block lines is counted once.
func TestFoldDedupesUsageByMessage(t *testing.T) {
	st := NewState()
	u := &agent.Usage{InputTokens: 10, CacheReadTokens: 90, OutputTokens: 5, ContextTokens: 100}
	for i := 0; i < 3; i++ {
		st.Step(agent.Event{Kind: agent.EventUsage, MessageID: "m1", Usage: u})
	}
	st.Step(agent.Event{Kind: agent.EventUsage, MessageID: "m2", Usage: u})
	// A turn-end cumulative frame has no context size and is not a request.
	st.Step(agent.Event{Kind: agent.EventUsage, Usage: &agent.Usage{InputTokens: 999}})
	if st.work != 210 {
		t.Fatalf("work = %d, want 210", st.work)
	}
}

// No edit at all: the prefix is the whole transcript.
func TestFoldNoEdit(t *testing.T) {
	st := NewState()
	ts := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	st.Step(agent.Event{Kind: agent.EventSystem, Cwd: "/w", TS: ts})
	call := func(id, tool, in string) {
		st.Step(agent.Event{Kind: agent.EventToolCall, Tool: &agent.ToolEvent{ID: id, Name: tool, Input: []byte(in)}})
		st.Step(agent.Event{Kind: agent.EventToolResult, Tool: &agent.ToolEvent{ID: id, Result: "ok"}})
	}
	call("a", "Read", `{"file_path":"/w/README.md"}`)
	call("b", "Read", `{"file_path":"/elsewhere/x.go"}`) // outside the worktree: not a codebase file
	call("c", "Glob", `{"pattern":"*.go"}`)
	got := st.Finalize(Diff{})
	if got.PrefixBasis != "no-edit" || got.ExplorationPrefixCalls != 2 || got.SearchPrefixCalls != 1 {
		t.Fatalf("got %+v", got)
	}
	if got.FilesReadDistinct != 1 || !reflect.DeepEqual(got.DocsRead, []string{"README.md"}) {
		t.Fatalf("reads: %d %v", got.FilesReadDistinct, got.DocsRead)
	}
}

// A successful Bash result that is a CLI rejecting its verb is still an
// env-discovery error: drv-043 ran a stale `draiver promote` with `; echo exit=$?`.
func TestFoldCobraUnknownOnSuccessfulBash(t *testing.T) {
	s := NewState()
	s.Step(agent.Event{Kind: agent.EventToolCall, Tool: &agent.ToolEvent{ID: "t1", Name: "Bash", Input: json.RawMessage(`{"command":"draiver promote local; echo exit=$?"}`)}})
	s.Step(agent.Event{Kind: agent.EventToolResult, Tool: &agent.ToolEvent{ID: "t1", Name: "Bash", Result: "draiver: unknown command \"promote\" for \"draiver\"\nexit=1"}})
	if got := s.Finalize(Diff{}).EnvDiscoveryErrors; got != 1 {
		t.Fatalf("env_discovery_errors = %d, want 1", got)
	}
}

// drv-057: a `cd` earlier in a Bash command moves where its relative paths resolve.
// drv-051's scratch work (`cd /tmp/drv051/frag && cat > drvctl-053.md <<EOF`) was
// counted as creating repo files; now paths that land outside the worktree drop out.
func TestFoldBashCdTracking(t *testing.T) {
	cases := []struct {
		name, cmd string
		edits     []string
	}{
		{"cd abs; cat >", "cd /tmp/x; cat > a.md <<'EOF'\nhi\nEOF", nil},
		{"cd abs && sed -i", "cd /tmp/x && sed -i 's/a/b/' a.md", nil},
		{"cd sub && cat >", "cd sub && cat > a.md <<'EOF'\nhi\nEOF", []string{"sub/a.md"}},
		{"cd newline", "cd /tmp/x\ncat > a.md <<'EOF'\nhi\nEOF", nil},
		{"cd into worktree", "cd /w/internal && cat > b.go <<'EOF'\nx\nEOF", []string{"internal/b.go"}},
		{"cd .. escapes", "cd .. && touch a.md", nil},
		{"cd sub then ..", "cd sub && cd .. && touch a.md", []string{"a.md"}},
		{"cd dynamic", "cd $TMPDIR && touch a.md", nil},
		{"cd dynamic then abs", "cd ~ && cd /w/pkg && touch a.md", []string{"pkg/a.md"}},
		{"abs path after cd unaffected", "cd /tmp/x && touch /w/c.md", []string{"c.md"}},
		{"python heredoc after cd", "cd /tmp/x && python3 - <<'EOF'\nopen('out.md', 'w').write('x')\nEOF", nil},
		{"no cd", "cat > a.md <<'EOF'\nhi\nEOF", []string{"a.md"}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			st := NewState()
			st.Step(agent.Event{Kind: agent.EventSystem, Cwd: "/w"})
			in, _ := json.Marshal(map[string]string{"command": c.cmd})
			st.Step(agent.Event{Kind: agent.EventToolCall, Tool: &agent.ToolEvent{ID: "t", Name: "Bash", Input: in}})
			st.Step(agent.Event{Kind: agent.EventToolResult, Tool: &agent.ToolEvent{ID: "t", Result: ""}})
			got := st.Finalize(Diff{Available: true, Files: map[string]bool{}, BaseFiles: map[string]bool{}})
			want := c.edits
			if want == nil {
				want = []string{}
			}
			if !reflect.DeepEqual(got.EditedFiles, want) {
				t.Fatalf("edited = %#v, want %#v", got.EditedFiles, want)
			}
			if !reflect.DeepEqual(got.TransientFiles, want) {
				t.Fatalf("transient = %#v, want %#v", got.TransientFiles, want)
			}
			if *got.RevertedEdits != len(want) {
				t.Fatalf("reverted_edits = %d, want %d", *got.RevertedEdits, len(want))
			}
		})
	}
}

// A `cd` moves reads too: `cd /tmp/x && cat notes.md` reads no repo file.
func TestFoldBashCdReads(t *testing.T) {
	st := NewState()
	st.Step(agent.Event{Kind: agent.EventSystem, Cwd: "/w"})
	for i, cmd := range []string{"cd /tmp/x && cat notes.md", "cd docs && cat guide.md"} {
		in, _ := json.Marshal(map[string]string{"command": cmd})
		id := string(rune('a' + i))
		st.Step(agent.Event{Kind: agent.EventToolCall, Tool: &agent.ToolEvent{ID: id, Name: "Bash", Input: in}})
		st.Step(agent.Event{Kind: agent.EventToolResult, Tool: &agent.ToolEvent{ID: id, Result: "x"}})
	}
	got := st.Finalize(Diff{})
	if got.FilesReadDistinct != 1 || !reflect.DeepEqual(got.DocsRead, []string{"docs/guide.md"}) {
		t.Fatalf("reads: %d %v", got.FilesReadDistinct, got.DocsRead)
	}
}
